package com.littlemakers.village.rendercheck;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;
/** Regression for the actual CreativeActivity bottom-Play screen reported by the user. */
public final class PlayroomCheck extends Instrumentation {
 private Activity playroom,menu,activity;private volatile Activity resumedStudio;private File out;private int passed;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 private void ui(Runnable r){java.util.concurrent.atomic.AtomicReference<Throwable>failure=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{r.run();}catch(Throwable e){failure.set(e);}});waitForIdleSync();if(failure.get()!=null)throw new AssertionError("UI operation failed",failure.get());}
 private Button find(View v,String label){if(v instanceof Button&&label.equals(((Button)v).getText().toString()))return(Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=find(((ViewGroup)v).getChildAt(i),label);if(b!=null)return b;}return null;}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private void click(String label){Foreground36.require(this,activity);ui(()->{Button b=find(activity.getWindow().getDecorView(),label);if(b==null)throw new AssertionError("Missing button "+label);b.performClick();});}
 private Activity studioFor(ActivityMonitor monitor,int expected)throws Exception{long end=SystemClock.uptimeMillis()+60000;while(SystemClock.uptimeMillis()<end){Activity candidate=resumedStudio;if(candidate!=null&&!candidate.isFinishing()&&candidate.getIntent().getIntExtra("mode",-1)==expected)return candidate;SystemClock.sleep(100);}throw new AssertionError("No resumed studio for mode "+expected);}

 private void screen(String name)throws Exception{waitForIdleSync();SystemClock.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("No screenshot");try(FileOutputStream f=new FileOutputStream(new File(out,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();passed++;Bundle status=new Bundle();status.putString("case",name);sendStatus(1,status);}
 @Override public void onStart(){Bundle result=new Bundle();try{
  ((Application)getTargetContext().getApplicationContext()).registerActivityLifecycleCallbacks(new Application.ActivityLifecycleCallbacks(){public void onActivityResumed(Activity a){if(a.getClass().getSimpleName().equals("StudioActivity"))resumedStudio=a;}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){if(resumedStudio==a)resumedStudio=null;}});out=new File(getTargetContext().getFilesDir(),"playroom-check");out.mkdirs();PackageInfo version=getTargetContext().getPackageManager().getPackageInfo("com.littlemakers.village",0);if(!version.versionName.equals("3.8.0-native"))throw new AssertionError("Wrong app build");
  activity=playroom=startActivitySync(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.CreativeActivity").putExtra("destination","play").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();Button banner=find(activity.getWindow().getDecorView(),"Adventures");if(banner==null)throw new AssertionError("Bottom-Play screen lacks launcher");ui(()->{int[]p=new int[2];banner.getLocationOnScreen(p);if(p[1]<0||p[1]+banner.getHeight()>activity.getWindow().getDecorView().getHeight())throw new AssertionError("New launcher is off screen");});screen("play-tab-launcher");
  ActivityMonitor m=addMonitor("com.littlemakers.village.nativeapp.QuestActivity",null,false);click("Adventures");menu=waitForMonitorWithTimeout(m,15000);removeMonitor(m);if(menu==null)throw new AssertionError("Banner did not launch catalog");activity=menu;waitForIdleSync();String[]names={"Number Guardians","Balance Workshop","Robot Routes","Discovery Trail","Letter Adventures","Learning Islands","Little Makers Friends","Shape Builders","Maker World"};for(String name:names)if(find(menu.getWindow().getDecorView(),name)==null)throw new AssertionError("Missing catalog option: "+name);screen("all-nine-catalog");
  for(int mode=0;mode<6;mode++){m=addMonitor("com.littlemakers.village.nativeapp.StudioActivity",null,false);click(names[mode+3]);Activity studio=studioFor(m,mode);removeMonitor(m);if(studio==null)throw new AssertionError("No studio for "+names[mode+3]);activity=studio;waitForIdleSync();if((Integer)field(field(studio,"state"),"mode")!=mode)throw new AssertionError("Wrong studio for "+names[mode+3]+"; expected "+mode+", actual "+field(field(studio,"state"),"mode")+", intent "+studio.getIntent().getIntExtra("mode",-1));if(mode==5)screen("maker-world-from-play");ActivityMonitor returning=addMonitor("com.littlemakers.village.nativeapp.QuestActivity",null,false);final Activity opened=studio;ui(opened::finish);Activity returned=waitForMonitorWithTimeout(returning,15000);removeMonitor(returning);if(returned==null)throw new AssertionError("Catalog did not resume");menu=returned;activity=menu;waitForIdleSync();}
  ActivityMonitor returningPlay=addMonitor("com.littlemakers.village.nativeapp.CreativeActivity",null,false);ui(()->menu.finish());Activity returnedPlay=waitForMonitorWithTimeout(returningPlay,15000);removeMonitor(returningPlay);if(returnedPlay==null)throw new AssertionError("Playroom did not resume");playroom=returnedPlay;activity=playroom;waitForIdleSync();if(find(playroom.getWindow().getDecorView(),"Adventures")==null)throw new AssertionError("Back lost playroom shortcut");ui(()->playroom.finish());result.putString("stream","PASS "+passed+" captures; 3.6 bottom-Play Adventures entry visible without scrolling; all nine catalog options present; six studio buttons launch the correct internal activities; Back returns to the same playroom\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){try{screen("failure");}catch(Exception ignored){}result.putString("stream","FAIL after "+passed+": "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
